1	/**
2	 * Testes co-located: integração dar_saida_requisicao em finalizarComSaida/finalizarSemSaida
3	 *
4	 * Cobre:
5	 *  1. RPC dar_saida_requisicao é chamada após transição de status bem-sucedida (com saída).
6	 *  2. alertas não-vazios disparam toast de warning (destructive).
7	 *  3. Falha na RPC reverte status para em_progresso e NÃO navega.
8	 *  4. "Finalizar" (sem saída) NÃO chama o RPC e navega para /logistica.
9	 *  5. Aviso de não-bipados aparece quando há item marcado sem bip.
10	 */
11	import {
12	  render,
13	  screen,
14	  waitFor,
15	  act,
16	  fireEvent,
17	} from '@testing-library/react';
18	import { describe, it, expect, vi, beforeEach } from 'vitest';
19	import PaginaPicking from './PaginaPicking.page';
20	import { BrowserRouter } from 'react-router-dom';
21	import * as routerDom from 'react-router-dom';
22	import { supabase } from '@/integrations/supabase/client';
23	
24	// ── mocks de módulos ────────────────────────────────────────────────────────
25	
26	// SaidaRequisicaoResumoDialog faz queries próprias ao Supabase; isolamos com stub.
27	vi.mock('./SaidaRequisicaoResumoDialog', () => ({
28	  SaidaRequisicaoResumoDialog: ({ open, onClose }: { open: boolean; onClose: () => void }) =>
29	    open ? (
30	      <div data-testid="resumo-saida-dialog">
31	        <button onClick={onClose}>Fechar</button>
32	      </div>
33	    ) : null,
34	}));
35	
36	vi.mock('react-router-dom', async () => {
37	  const actual = await vi.importActual('react-router-dom');
38	  return {
39	    ...(actual as Record<string, unknown>),
40	    useParams: vi.fn(),
41	    useNavigate: vi.fn(),
42	  };
43	});
44	
45	vi.mock('@/shared/hooks/useAuth', () => ({
46	  useAuth: () => ({
47	    user: { id: 'mock-user-id', user_metadata: { full_name: 'Operador Teste' } },
48	    userProfile: { nome: 'Operador Teste' },
49	  }),
50	}));
51	
52	vi.mock('@/shared/hooks/usePermissions', () => ({
53	  usePermissions: () => ({
54	    canViewRequisicao: () => true,
55	    canEditRequisicao: () => true,
56	  }),
57	}));
58	
59	vi.mock('@/shared/contexts/StoreContext', () => ({
60	  useStore: () => ({ stores: [] }),
61	}));
62	
63	vi.mock('@/shared/hooks/use-mobile', () => ({
64	  useIsMobile: () => false,
65	  useIsTablet: () => false,
66	}));
67	
68	vi.mock('@/shared/lib/expedition-log-service', () => ({
69	  logExpeditionEvent: vi.fn().mockResolvedValue(undefined),
70	  logSeparationCompleted: vi.fn().mockResolvedValue(undefined),
71	}));
72	
73	// Toast mock: precisamos espioná-lo para verificar chamadas.
74	const mockToast = vi.fn();
75	vi.mock('@/shared/hooks/use-toast', () => ({
76	  useToast: () => ({ toast: mockToast }),
77	}));
78	
79	// Supabase é re-mockado aqui em nível de teste (sobrescreve o global de setup.ts)
80	vi.mock('@/integrations/supabase/client', () => ({
81	  supabase: {
82	    from: vi.fn(),
83	    channel: vi.fn(),
84	    removeChannel: vi.fn().mockResolvedValue(undefined),
85	    rpc: vi.fn(),
86	    auth: {
87	      getUser: vi
88	        .fn()
89	        .mockResolvedValue({ data: { user: { id: 'mock-user-id' } }, error: null }),
90	    },
91	  },
92	}));
93	
94	class StubResizeObserver {
95	  observe() {}
96	  unobserve() {}
97	  disconnect() {}
98	}
99	window.ResizeObserver = StubResizeObserver;
100	Element.prototype.scrollIntoView = vi.fn();
101	
102	// ── helpers de mock ─────────────────────────────────────────────────────────
103	
104	const mockNavigate = vi.fn();
105	
106	const mockChannel = {
107	  on: vi.fn().mockReturnThis(),
108	  subscribe: vi.fn((cb?: (status: string) => void) => {
109	    if (typeof cb === 'function') cb('SUBSCRIBED');
110	    return mockChannel;
111	  }),
112	  track: vi.fn(),
113	  untrack: vi.fn(),
114	  send: vi.fn(),
115	  unsubscribe: vi.fn(),
116	  presenceState: vi.fn(() => ({})),
117	};
118	
119	const mockReqInfo = {
120	  id: 123,
121	  nome: 'Req #123',
122	  solicitante: 'Ana',
123	  loja_solicitante: 'Asa Sul',
124	  loja_preparadora: 'Fábrica',
125	  data_pedido: '2026-06-01',
126	  data_recebimento: null,
127	  subtitle: null,
128	};
129	
130	// Itens com quantidade_enviada preenchida — permite que os botões Finalizar sejam habilitados.
131	const mockItensColetados = [
132	  {
133	    id: 10,
134	    nome_produto: 'Brownie',
135	    quantidade_solicitada: 5,
136	    quantidade_enviada: '5',
137	    observacao: '',
138	    category: 'Geral',
139	    ordem: 1,
140	    lote: '',
141	    validade: '',
142	    produto_id: null,
143	  },
144	];
145	
146	const makeChainable = (table: string) => {
147	  const c: Record<string, ReturnType<typeof vi.fn> | ((resolve: (v: { data: unknown; error: null }) => void) => unknown)> = {
148	    select: vi.fn(() => c),
149	    eq: vi.fn(() => c),
150	    order: vi.fn(() => c),
151	    limit: vi.fn(() => c),
152	    in: vi.fn(() => c),
153	    not: vi.fn(() => c),
154	    ilike: vi.fn(() => c),
155	    or: vi.fn(() => c),
156	    gt: vi.fn(() => c),
157	    gte: vi.fn(() => c),
158	    lte: vi.fn(() => c),
159	    update: vi.fn(() => c),
160	    insert: vi.fn(() => c),
161	    delete: vi.fn(() => c),
162	    maybeSingle: vi.fn(() => Promise.resolve({ data: null, error: null })),
163	    single: vi.fn(() =>
164	      Promise.resolve({
165	        data: table === 'requisicoes' ? mockReqInfo : mockItensColetados[0],
166	        error: null,
167	      }),
168	    ),
169	    then: (resolve: (v: { data: unknown; error: null }) => void) => {
170	      if (table === 'requisicoes')
171	        return resolve({ data: mockReqInfo, error: null });
172	      if (table === 'requisicoes_itens')
173	        return resolve({ data: mockItensColetados, error: null });
174	      if (table === 'profiles')
175	        return resolve({
176	          data: { nome: 'Operador Teste', username: 'operador' },
177	          error: null,
178	        });
179	      // etiquetas_qr_eventos e etiquetas_qr: por padrão retornam lista vazia
180	      // (nenhum bip) — o item Brownie (produto_id: null, masterId indefinido)
181	      // seria detectado como não-bipado. Isso dispara o dialog de aviso.
182	      return resolve({ data: [], error: null });
183	    },
184	  };
185	  return c;
186	};
187	
188	/** Configura supabase.from + channel + rpc conforme cenário. */
189	const setupSupabaseMock = ({
190	  rpcResult,
191	  etiquetasQrEventos = [],
192	  etiquetasQr = [],
193	}: {
194	  rpcResult: { data: unknown; error: null | { message: string } };
195	  etiquetasQrEventos?: unknown[];
196	  etiquetasQr?: unknown[];
197	}) => {
198	  (supabase.from as ReturnType<typeof vi.fn>).mockImplementation((table: string) => {
199	    const c = makeChainable(table);
200	    // UPDATE atômico de status: retornar 1 row para simular sucesso de reserva.
201	    if (table === 'requisicoes') {
202	      c.update = vi.fn(() => {
203	        const upChain = { ...c };
204	        upChain.eq = vi.fn(() => upChain);
205	        upChain.select = vi.fn(() =>
206	          Promise.resolve({ data: [{ id: 123 }], error: null }),
207	        );
208	        return upChain;
209	      });
210	    }
211	    if (table === 'etiquetas_qr_eventos') {
212	      // Precisa resolver via .then() mas a chain usa .in() que retorna a chain
213	      // O then() será chamado pela promise implícita
214	      const eventos = etiquetasQrEventos;
215	      const qrEvChain = {
216	        ...c,
217	        then: (resolve: (v: { data: unknown; error: null }) => void) =>
218	          resolve({ data: eventos, error: null }),
219	      };
220	      qrEvChain.select = vi.fn(() => qrEvChain);
221	      qrEvChain.eq = vi.fn(() => qrEvChain);
222	      qrEvChain.in = vi.fn(() =>
223	        Promise.resolve({ data: eventos, error: null }),
224	      );
225	      return qrEvChain;
226	    }
227	    if (table === 'etiquetas_qr') {
228	      const tags = etiquetasQr;
229	      const qrChain = {
230	        ...c,
231	        then: (resolve: (v: { data: unknown; error: null }) => void) =>
232	          resolve({ data: tags, error: null }),
233	      };
234	      qrChain.select = vi.fn(() => qrChain);
235	      qrChain.in = vi.fn(() =>
236	        Promise.resolve({ data: tags, error: null }),
237	      );
238	      return qrChain;
239	    }
240	    return c;
241	  });
242	  (supabase.channel as ReturnType<typeof vi.fn>).mockReturnValue(mockChannel);
243	  (supabase.rpc as ReturnType<typeof vi.fn>).mockResolvedValue(rpcResult);
244	};
245	
246	const renderComponent = () =>
247	  render(
248	    <BrowserRouter>
249	      <PaginaPicking />
250	    </BrowserRouter>,
251	  );
252	
253	/** Aguarda o carregamento inicial do componente. */
254	const waitForLoad = () =>
255	  waitFor(() => expect(screen.getByText('Brownie')).toBeInTheDocument(), {
256	    timeout: 5000,
257	  });
258	
259	/**
260	 * Clica em "Finalizar e dar saída".
261	 * Se o dialog de aviso de não-bipados aparecer, clica em "Dar saída só dos bipados"
262	 * para que o fluxo do RPC seja exercitado nos testes existentes.
263	 */
264	const clickFinalizarComSaida = async () => {
265	  const btn = screen.getByRole('button', { name: /finalizar e dar sa[ií]da/i });
266	  await act(async () => {
267	    fireEvent.click(btn);
268	  });
269	  // Se o dialog de aviso aparecer (itens sem bip), confirmar para prosseguir ao RPC
270	  const confirmarBtn = screen.queryByRole('button', { name: /dar sa[ií]da s[oó] dos bipados/i });
271	  if (confirmarBtn) {
272	    await act(async () => {
